// Initialize
let cart = {{.Trigger.cart}}.cart_list;

// Calculate overall total
let overallTotal = SUM_LIST(list=cart, 'totalPrice');

// Initialize result array
let result = [
  {
    type: "overall",
    name: "Payment Gateway",
    value: overallTotal
  },
];

// Calculate Category Totals
cart.map(item => item.category).filter((value, index, self) => self.indexOf(value) === index).forEach(category => {
  let categoryTotal = SUM_LIST(list=FILTER(cart, "$item.$category === '" + category + "'"), 'totalPrice');
  result.push({
    type: "category",
    name: category,
    value: categoryTotal
  });
});

// Calculate Brand Totals
cart.map(item => item.brand).filter((value, index, self) => self.indexOf(value) === index).forEach(brand => {
  let brandTotal = SUM_LIST(list=FILTER(cart, "$item.$brand === '" + brand + "'"), 'totalPrice');
  result.push({
    type: "brand",
    name: brand,
    value: brandTotal
  });
});

result;

const data = {{.Zepto_Coupons_Each.output}};
const coupons = [];

data.forEach(group => {
  if (Array.isArray(group.output)) {
    group.output.forEach(coupon => {
      coupons.push(coupon);
    });
  }
});

const uniqueCoupons = [];
const seenCodes = {};

coupons.forEach(coupon => {
  if (!seenCodes[coupon.code]) {
    seenCodes[coupon.code] = true;
    uniqueCoupons.push(coupon);
  }
});

coupons
